import { configure } from 'enzyme';
import Adapter from 'enzyme-adapter-react-16';
import 'jest-localstorage-mock';

configure({ adapter: new Adapter() });

import { Component } from 'react';
import PropTypes from 'prop-types';

export default class StorageErrorBoundary extends Component {
  static propTypes = {
    children: PropTypes.node.isRequired,
  };

  componentDidCatch(err) {
    localStorage.clear();
    throw err;
  }

  render() {
    return this.props.children;
  }
}

import React from 'react';
import Index from '../../pages/index';
import CardManager from '../../components/CardManager';
import MainHeader from '../../components/MainHeader';
import { mount } from 'enzyme';

describe('Index', () => {
  test('cards are cleared', () => {
    const wrapper = mount(<Index />);
    const clearCards = jest.fn();
    wrapper.find(CardManager).instance().clearCards = clearCards;

    wrapper
      .find(MainHeader)
      .find('a')
      .at(0)
      .simulate('click');

    expect(clearCards.mock.calls).toHaveLength(1);
  });
});

import Iconify from '../../components/Iconify';
import { mount } from 'enzyme';
import { Icon } from 'semantic-ui-react';

const render = (children, shadow = false) =>
  mount(
    <span>
      <Iconify shadow={shadow}>{children}</Iconify>
    </span>
  );

describe('Iconify', () => {
  test('leaves plain text alone', () => {
    const wrapper = render('hi');

    expect(wrapper.text()).toBe('hi');
  });

  test('converts icon within other text', () => {
    const wrapper = render('You gotta pay {7} or lose the game.');

    expect(wrapper.html()).toContain(
      'You gotta pay <i class="ms ms-7 ms-cost" title="{7}"></i> or lose the game.'
    );
  });

  test('converts sibling icons', () => {
    const wrapper = render('{1}{G}{B}');

    expect(wrapper.find('i')).toHaveLength(3);
    expect(
      wrapper
        .find('i')
        .at(0)
        .prop('className')
    ).toBe('ms ms-1 ms-cost');
    expect(
      wrapper
        .find('i')
        .at(0)
        .prop('title')
    ).toBe('{1}');
    expect(
      wrapper
        .find('i')
        .at(1)
        .prop('className')
    ).toBe('ms ms-g ms-cost');
    expect(
      wrapper
        .find('i')
        .at(1)
        .prop('title')
    ).toBe('{G}');
    expect(
      wrapper
        .find('i')
        .at(2)
        .prop('className')
    ).toBe('ms ms-b ms-cost');
    expect(
      wrapper
        .find('i')
        .at(2)
        .prop('title')
    ).toBe('{B}');
  });

  test('applies shadow class', () => {
    const wrapper = render('{100}', true);

    expect(wrapper.find('i')).toHaveLength(1);
    expect(
      wrapper
        .find('i')
        .at(0)
        .prop('className')
    ).toBe('ms ms-100 ms-cost ms-shadow');
    expect(
      wrapper
        .find('i')
        .at(0)
        .prop('title')
    ).toBe('{100}');
  });

  describe('beginning of line', () => {
    test('converts 0:', () => {
      const wrapper = render('0: give up');

      expect(wrapper.html()).toBe(
        '<span><i title="0 Loyalty" class="ms ms-loyalty-zero ms-loyalty-0"></i>: give up</span>'
      );
    });

    test('converts −3:', () => {
      const wrapper = render('−3: do a cool thing');

      expect(wrapper.html()).toBe(
        '<span><i title="-3 Loyalty" class="ms ms-loyalty-down ms-loyalty-3"></i>: do a cool thing</span>'
      );
    });

    test('converts +1:', () => {
      const wrapper = render('+1: do a mediocre thing');

      expect(wrapper.html()).toBe(
        '<span><i title="+1 Loyalty" class="ms ms-loyalty-up ms-loyalty-1"></i>: do a mediocre thing</span>'
      );
    });
  });
});

import React from 'react';
import OracleModal from '../../components/OracleModal';
import CardImage from '../../components/CardImage';
import { Modal, Button, Segment } from 'semantic-ui-react';
import { mount } from 'enzyme';

describe('OracleModal', () => {
  afterEach(() => {
    const modal = document.querySelector('.modal');
    if (modal) modal.remove();
  });

  const mockCard = {
    id: '1',
    color_identity: 'u',
    mana_cost: '{U}',
    name: 'Swan Song',
    oracle_text:
      'Counter target enchantment, instant, or sorcery spell. Its controller creates a 2/2 blue Bird creature token with flying.',
    power: null,
    toughness: null,
    type_line: 'Instant',
    flavor_text:
      '“The most enlightened mages create beauty from violence.” —Medomai the Ageless',
    loyalty: null,
    image_uris: {
      large: 'hi',
    },
  };
  const mockCardWithFaces = {
    card_faces: [
      {
        id: '1',
        color_identity: 'u',
        mana_cost: '{U}',
        name: 'Swan Song 1',
        oracle_text:
          'Counter target enchantment, instant, or sorcery spell. Its controller creates a 2/2 blue Bird creature token with flying.',
        power: null,
        toughness: null,
        type_line: 'Instant',
        flavor_text:
          '“The most enlightened mages create beauty from violence.” —Medomai the Ageless',
        loyalty: null,
        image_uris: {
          large: 'hi 1',
        },
      },
      {
        id: '1',
        color_identity: 'u',
        mana_cost: '{U}',
        name: 'Swan Song 2',
        oracle_text:
          'Counter target enchantment, instant, or sorcery spell. Its controller creates a 2/2 blue Bird creature token with flying.',
        power: null,
        toughness: null,
        type_line: 'Instant',
        flavor_text:
          '“The most enlightened mages create beauty from violence.” —Medomai the Ageless',
        loyalty: null,
        image_uris: {
          large: 'hi 2',
        },
      },
    ],
  };

  test('renders a trigger button', () => {
    const wrapper = mount(<OracleModal card={mockCard} />);

    expect(wrapper.find(Button)).toHaveLength(1);
    expect(wrapper.find(Button).prop('title')).toEqual('Oracle');
  });

  test('renders single faced card data', () => {
    const wrapper = mount(<OracleModal card={mockCard} />);
    wrapper.find(Button).simulate('click');

    const modal = document.querySelector('.modal');
    expect(modal).toBeDefined();
    expect(modal.querySelectorAll('.segment')).toHaveLength(1);
    expect(modal.querySelector('.segment').innerHTML).toContain('Swan Song');
    expect(modal.querySelector('.segment').innerHTML).toContain(
      'Counter target enchantment, instant, or sorcery spell. Its controller creates a 2/2 blue Bird creature token with flying.'
    );
  });

  test('renders double faced card data', () => {
    const wrapper = mount(<OracleModal card={mockCardWithFaces} />);
    wrapper.find(Button).simulate('click');

    const modal = document.querySelector('.modal');
    expect(modal).toBeDefined();
    expect(modal.querySelectorAll('.segment')).toHaveLength(2);
    expect(modal.querySelectorAll('.segment')[0].innerHTML).toContain(
      'Swan Song 1'
    );
    expect(modal.querySelectorAll('.segment')[0].innerHTML).toContain(
      'Counter target enchantment, instant, or sorcery spell. Its controller creates a 2/2 blue Bird creature token with flying.'
    );
    expect(modal.querySelectorAll('.segment')[1].innerHTML).toContain(
      'Swan Song 2'
    );
    expect(modal.querySelectorAll('.segment')[1].innerHTML).toContain(
      'Counter target enchantment, instant, or sorcery spell. Its controller creates a 2/2 blue Bird creature token with flying.'
    );
  });

  // These tests are difficult because semantic ui portal rendering is not supported here.
  test('renders the card image', () => {
    const wrapper = mount(<OracleModal card={mockCard} />);
    wrapper.find(Button).simulate('click');

    const modal = document.querySelector('.modal');
    expect(modal).toBeDefined();
    expect(modal.querySelectorAll('.spin.front')).toHaveLength(1);
  });

  test('renders both card faces', () => {
    const wrapper = mount(<OracleModal card={mockCardWithFaces} />);
    wrapper.find(Button).simulate('click');

    const modal = document.querySelector('.modal');
    expect(modal).toBeDefined();
    expect(modal.querySelectorAll('.spin.front')).toHaveLength(2);
  });
});

import React from 'react';
import fetchMock from 'fetch-mock';
import CardFinder from '../../components/CardFinder';
import { mount } from 'enzyme';

describe('CardFinder', () => {
  afterEach(() => {
    fetchMock.restore();
  });

  test('searches for cards on input', () => {
    fetchMock.mock('*', {
      data: ['Serra Angel'],
    });

    const wrapper = mount(<CardFinder onCardSelected={() => null} />);

    wrapper
      .find('input')
      .simulate('change', { target: { value: 'Serra Angel' } });
    expect(fetchMock.called()).toBe(true);
    expect(fetchMock.lastUrl()).toEqual(
      'https://api.scryfall.com/cards/autocomplete?q=Serra%20Angel'
    );
  });

  test('does not search for input < 3 characters', () => {
    fetchMock.mock('*', {
      data: ['Serra Angel'],
    });

    const wrapper = mount(<CardFinder onCardSelected={() => null} />);

    wrapper.find('input').simulate('change', { target: { value: '' } });
    wrapper.find('input').simulate('change', { target: { value: 'S' } });
    wrapper.find('input').simulate('change', { target: { value: 'Se' } });
    expect(fetchMock.called()).toBe(false);

    wrapper.find('input').simulate('change', { target: { value: 'Ser' } });
    expect(fetchMock.called()).toBe(true);
  });

  test('sets results after searchings cards', done => {
    fetchMock.mock('*', {
      data: ['Serra Angel'],
    });

    const wrapper = mount(<CardFinder onCardSelected={() => null} />);

    wrapper
      .find('input')
      .simulate('change', { target: { value: 'Serra Angel' } });

    setTimeout(() => {
      expect(wrapper.state().results).toEqual([{ title: 'Serra Angel' }]);
      done();
    }, 1);
  });

  test('renders results', () => {
    const wrapper = mount(<CardFinder onCardSelected={() => null} />);
    wrapper.setState({
      results: [
        {
          title: 'Goblin Spy',
        },
        {
          title: 'Goblin Lore',
        },
        {
          title: 'Goblin King',
        },
      ],
    });

    expect(wrapper.find('.result')).toHaveLength(3);
    expect(
      wrapper
        .find('.result')
        .at(0)
        .text()
    ).toEqual('Goblin Spy');
    expect(
      wrapper
        .find('.result')
        .at(1)
        .text()
    ).toEqual('Goblin Lore');
    expect(
      wrapper
        .find('.result')
        .at(2)
        .text()
    ).toEqual('Goblin King');
  });

  test('invokes onCardSelected', () => {
    const onCardSelected = jest.fn();
    const wrapper = mount(<CardFinder onCardSelected={onCardSelected} />);
    wrapper.setState({ results: [{ title: 'Serra Angel' }] });

    wrapper.find('.result').simulate('click', {
      nativeEvent: {
        stopImmediatePropagation: () => null,
      },
    });

    expect(onCardSelected.mock.calls).toHaveLength(1);
    expect(onCardSelected.mock.calls[0][0]).toEqual('Serra Angel');
  });
});

import {
