import React from 'react';
import fetchMock from 'fetch-mock';
import CardManager from '../../components/CardManager';
import CardFinder from '../../components/CardFinder';
import CardResult from '../../components/CardResult';
import { Button } from 'semantic-ui-react';
import { shallow, mount } from 'enzyme';

describe('CardManager', () => {
  const mockCardData = {
    image_uris: {
      large: 'image uri',
    },
    scryfall_uri: 'card uri',
    rulings_uri: 'rulings uri',
  };
  const mockRulingsData = {
    data: [],
  };

  beforeEach(() => {
    fetchMock.get(
      'begin:https://api.scryfall.com/cards/named?exact=',
      mockCardData
    );
    fetchMock.get('rulings uri', mockRulingsData);
    localStorage.clear();
  });

  afterEach(() => {
    fetchMock.restore();
  });

  test('renders just the CardFinder to start', () => {
    const wrapper = shallow(<CardManager />);

    expect(wrapper.find(CardFinder)).toHaveLength(1);
    expect(wrapper.find(CardResult)).toHaveLength(0);
  });

  test('adds new cards', done => {
    const wrapper = mount(<CardManager />);
    wrapper
      .find(CardFinder)
      .at(0)
      .prop('onCardSelected')('Serra Angel');
    wrapper.update();

    expect(wrapper.find(CardResult)).toHaveLength(1);
    expect(
      wrapper
        .find(CardResult)
        .at(0)
        .prop('name')
    ).toEqual('Serra Angel');

    wrapper
      .find(CardFinder)
      .at(0)
      .prop('onCardSelected')('Goblin King');
    wrapper.update();

    expect(wrapper.find(CardResult)).toHaveLength(2);
    expect(
      wrapper
        .find(CardResult)
        .at(1)
        .prop('name')
    ).toEqual('Goblin King');

    // When mounting, the CardResults fetch data. They haven't finished at this
    // point, but they will after the next tick. If we don't do this, we'll
    // unmock fetch before they call it and we get a warning.
    setImmediate(done);
  });

  test('removes cards', () => {
    const wrapper = shallow(<CardManager />);
    wrapper
      .find(CardFinder)
      .at(0)
      .prop('onCardSelected')('Serra Angel');
    wrapper
      .find(CardFinder)
      .at(0)
      .prop('onCardSelected')('Lightning Bolt');
    wrapper
      .find(CardFinder)
      .at(0)
      .prop('onCardSelected')('Goblin King');
    wrapper.update();

    expect(wrapper.find(CardResult)).toHaveLength(3);

    wrapper
      .find(CardResult)
      .at(1)
      .prop('onRequestRemove')();
    wrapper.update();

    expect(wrapper.find(CardResult)).toHaveLength(2);
    expect(
      wrapper
        .find(CardResult)
        .at(0)
        .prop('name')
    ).toEqual('Serra Angel');
    expect(
      wrapper
        .find(CardResult)
        .at(1)
        .prop('name')
    ).toEqual('Goblin King');
  });

  test('clears cards', () => {
    const wrapper = shallow(<CardManager />);
    wrapper
      .find(CardFinder)
      .at(0)
      .prop('onCardSelected')('Serra Angel');
    wrapper
      .find(CardFinder)
      .at(0)
      .prop('onCardSelected')('Lightning Bolt');
    wrapper
      .find(CardFinder)
      .at(0)
      .prop('onCardSelected')('Goblin King');
    wrapper.update();

    expect(wrapper.find(CardResult)).toHaveLength(3);

    wrapper.instance().clearCards();

    expect(wrapper.find(CardResult)).toHaveLength(3);
  });

  test('does not clear pinned cards', () => {
    const wrapper = shallow(<CardManager />);
    wrapper
      .find(CardFinder)
      .at(0)
      .prop('onCardSelected')('Serra Angel');
    wrapper
      .find(CardFinder)
      .at(0)
      .prop('onCardSelected')('Lightning Bolt');
    wrapper
      .find(CardFinder)
      .at(0)
      .prop('onCardSelected')('Goblin King');

    wrapper.update();
    wrapper
      .find(CardResult)
      .at(1)
      .prop('onRequestPin')();
    wrapper.update();
    expect(wrapper.find(CardResult)).toHaveLength(3);
    wrapper.instance().clearCards();
    wrapper.update();
    expect(wrapper.find(CardResult)).toHaveLength(1);
    expect(wrapper.find(CardResult).prop('name')).toEqual('Lightning Bolt');
  });

  describe('retrieveSavedState', () => {
    test('is default state if no storage exists', () => {
      localStorage.clear();

      const manager = shallow(<CardManager />).instance();
      expect(manager.retrieveSavedState()).toEqual({ cards: [] });
    });

    test('is default state if no storage is bogus', () => {
      localStorage.setItem('CardManager#state', 'BOGUS');

      const manager = shallow(<CardManager />).instance();
      expect(manager.retrieveSavedState()).toEqual({ cards: [] });
    });

    test('is from storage', () => {
      localStorage.setItem(
        'CardManager#state',
        JSON.stringify({
          cards: [{ name: 'Fling', isPinned: true }],
        })
      );

      const manager = shallow(<CardManager />).instance();
      expect(manager.retrieveSavedState()).toEqual({
        cards: [{ name: 'Fling', isPinned: true }],
      });
    });
  });

  describe('componentDidMount', () => {
    test('updates state to saved state', () => {
      localStorage.setItem(
        'CardManager#state',
        JSON.stringify({
          cards: [{ name: 'Fling', isPinned: true }],
        })
      );

      const wrapper = shallow(<CardManager />);
      wrapper.update();

      expect(wrapper.find(CardResult)).toHaveLength(1);
      expect(wrapper.find(CardResult).prop('name')).toBe('Fling');
      expect(wrapper.find(CardResult).prop('isPinned')).toBe(true);
    });
  });

  describe('componentDidUpdate', () => {
    test('saves state', () => {
      const wrapper = shallow(<CardManager />);

      wrapper.setState({ cards: [{ name: 'Fling', isPinned: true }] });

      expect(localStorage.getItem('CardManager#state')).toEqual(
        '{"cards":[{"name":"Fling","isPinned":true}]}'
      );
    });
  });
});

import PowerToughness from '../../components/PowerToughness';
import { shallow } from 'enzyme';
import { Icon } from 'semantic-ui-react';

describe('PowerToughness', () => {
  test('renders numbers', () => {
    const wrapper = shallow(<PowerToughness power="3" toughness="7" />);

    expect(wrapper.find('i')).toHaveLength(4);
    expect(
      wrapper
        .find('i')
        .at(0)
        .is('.ms-3')
    ).toBe(true);
    expect(
      wrapper
        .find('i')
        .at(1)
        .is('.ms-power')
    ).toBe(true);
    expect(
      wrapper
        .find('i')
        .at(2)
        .is('.ms-7')
    ).toBe(true);
    expect(
      wrapper
        .find('i')
        .at(3)
        .is('.ms-toughness')
    ).toBe(true);
    expect(wrapper.html()).toContain(' / ');
  });

  test('renders stars', () => {
    const wrapper = shallow(<PowerToughness power="*" toughness="*" />);

    expect(wrapper.find('i')).toHaveLength(2);
    expect(wrapper.find(Icon)).toHaveLength(2);
    expect(
      wrapper
        .find(Icon)
        .at(0)
        .prop('name')
    ).toBe('star');
    expect(
      wrapper
        .find(Icon)
        .at(1)
        .prop('name')
    ).toBe('star');
    expect(
      wrapper
        .find('i')
        .at(0)
        .is('.ms-power')
    ).toBe(true);

    expect(
      wrapper
        .find('i')
        .at(1)
        .is('.ms-toughness')
    ).toBe(true);
    expect(wrapper.html()).toContain(' / ');
